/* Modern alert: leading status icon + neutral, readable text on a lightly
 * tinted surface with a soft colored border. The icon and border carry the
 * tone; the text stays neutral (not a saturated fill + colored text). */
.alert {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--card);

  color: var(--foreground);
  font-size: var(--font-sm);
  line-height: var(--leading-snug);
}
.alert-icon { flex: none; margin-block-start: 1px; color: var(--muted-foreground); }
.alert-body { min-width: 0; }

/* Trailing action (message + a button): pinned to the end; the row wraps so the
 * action drops below the text on narrow widths. */
.alert:has(.alert-action) { flex-wrap: wrap; column-gap: var(--space-3); }
.alert-action { flex: none; margin-inline-start: auto; align-self: center; }

/* Dismiss sits after the action, hugging the top edge so it stays put when the
 * body runs to several lines. `auto` here only bites when there is no action. */
.alert-dismiss { flex: none; margin-inline-start: auto; align-self: flex-start; }
.alert-action + .alert-dismiss { margin-inline-start: 0; }
.alert[data-compact] .alert-dismiss { align-self: center; }

/* Compact — dense single-line strip (inline assist rows, list-level notices). */
.alert[data-compact] {
  align-items: center;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
}
.alert[data-compact] .alert-icon { margin-block-start: 0; }

/* Tint + a tone-matched edge. The tint alone is not enough: an info notice on
 * the --muted page surface, or a pale success notice on a light card, had no
 * outline left and dissolved into the background. The border is what makes the
 * alert a shape on ANY surface; the icon still carries the emphasis colour. */
.alert[data-tone="neutral"] { background: var(--muted); border-color: var(--border-strong); }
.alert[data-tone="info"]    { background: var(--primary-soft); border-color: var(--primary-border); }
.alert[data-tone="danger"]  { background: var(--destructive-soft); border-color: var(--destructive-border); }
.alert[data-tone="warning"] { background: var(--warning-soft); border-color: var(--warning-border); }
.alert[data-tone="success"] { background: var(--success-soft); border-color: var(--success-border); }
.alert[data-tone="info"]    .alert-icon { color: var(--primary-soft-foreground); }
.alert[data-tone="danger"]  .alert-icon { color: var(--destructive-emphasis); }
.alert[data-tone="warning"] .alert-icon { color: var(--warning-emphasis); }
.alert[data-tone="success"] .alert-icon { color: var(--success-emphasis); }

import './Alert.css'
import type { HTMLAttributes, ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import { cn } from '../lib/cn'
import { Icon, type IconName } from '../Icon'
import { IconButton } from '../IconButton'
import { Tooltip } from '../Tooltip'

type Tone = 'neutral' | 'danger' | 'warning' | 'success' | 'info'

const TONE_ICON: Record<Tone, IconName> = {
  neutral: 'info',
  info: 'info',
  success: 'check_circle',
  warning: 'warning',
  danger: 'error',
}

type Props = HTMLAttributes<HTMLDivElement> & {
  tone?: Tone
  /** Override the tone icon (e.g. `sparkles` for AI-assist messages). */
  icon?: IconName
  /** Dense one-line variant: small padding, centred icon. */
  compact?: boolean
  /** Trailing action (e.g. a Button), pinned to the end of the alert row. */
  action?: ReactNode
  /* Dismissal is the consumer's job because the alert does not own its own
   * mounting: pass a handler and a close button appears. Suits info, success
   * and neutral notices; a warning or an error the user has not resolved yet
   * should stay on screen, so do not pass it there. */
  onDismiss?: () => void
}

/**
 * Inline message on a region: `tone` carries the meaning and `onDismiss` makes
 * it dismissible. Default role is status; pass role="alert" for an error.
 * Dismiss info and success, never an unresolved error.
 *
 * Copy: one sentence about what happened, in the reader's terms, not the
 * system's. A tone is not a substitute for words: "Saved" and "Could not
 * save — the file is open elsewhere" both need saying.
 */
export function Alert({ tone = 'info', icon, compact, action, onDismiss, className, role = 'status', children, ...rest }: Props) {
  const { t } = useTranslation()
  return (
    <div
      className={cn('alert', className)} data-raised="card"
      data-tone={tone}
      data-compact={compact || undefined}
      role={role}
      {...rest}
    >
      <Icon name={icon ?? TONE_ICON[tone]} className="alert-icon" />
      <div className="alert-body">{children}</div>
      {action && <div className="alert-action">{action}</div>}
      {onDismiss && (
        <Tooltip content={t('a11y.dismiss')}>
          <IconButton
            icon="close"
            variant="quiet"
            size="sm"
            className="alert-dismiss"
            aria-label={t('a11y.dismiss')}
            onClick={onDismiss}
          />
        </Tooltip>
      )}
    </div>
  )
}
